/* LOVE STK GROUPE — news page */
/* Source: theme.js */
(()=>{
 const root=document.documentElement,key='stk-theme',media=window.matchMedia('(prefers-color-scheme: dark)');
 let mode='dark';try{const saved=localStorage.getItem(key);if(['dark','light','auto'].includes(saved))mode=saved}catch{}
 const words={th:['โหมดการแสดงผล','มืด','สว่าง','ตามระบบ'],lo:['ຮູບແບບການສະແດງ','ມືດ','ສະຫວ່າງ','ຕາມລະບົບ'],en:['Appearance','Dark','Light','Auto']};
 function apply(){root.dataset.themeMode=mode;root.dataset.theme=mode==='auto'?(media.matches?'dark':'light'):mode;const select=document.querySelector('.theme-select');if(select)select.value=mode;const label=document.querySelector('.theme-control');if(label)label.dataset.mode=mode;}
 function localize(){const t=words[root.lang]||words.th;const select=document.querySelector('.theme-select');if(!select)return;select.setAttribute('aria-label',t[0]);select.title=t[0];[...select.options].forEach((o,i)=>o.textContent=t[i+1]);}
 apply();
 document.addEventListener('DOMContentLoaded',()=>{const select=document.querySelector('.theme-select');if(!select)return;apply();localize();select.addEventListener('change',()=>{mode=select.value;try{localStorage.setItem(key,mode)}catch{}apply();});});
 media.addEventListener('change',()=>{if(mode==='auto')apply()});document.addEventListener('stk-language-change',localize);
 window.addEventListener('storage',e=>{if(e.key===key){mode=['dark','light','auto'].includes(e.newValue)?e.newValue:'dark';apply()}});
})();

