function setLanguage(lang){if(!translations[lang])lang='th';document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>{el.innerHTML=translations[lang][el.dataset.i]||original[el.dataset.i]});document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));document.querySelector('meta[name=description]').content=document.documentElement.dataset.page==='news'?translations[lang].newsIntro:document.documentElement.dataset.page==='leadership'?translations[lang].leadershipIntro:translations[lang].aboutDesc;document.title='LOVE STK GROUPE — '+({th:'เกี่ยวกับบริษัท',lo:'ກ່ຽວກັບບໍລິສັດ',en:'Our company'})[lang];if(document.documentElement.dataset.page==='leadership')document.title=({th:'ผู้บริหาร CEO · CFO · COO',lo:'ຜູ້ບໍລິຫານ CEO · CFO · COO',en:'Leadership · CEO · CFO · COO'})[lang]+' — LOVE STK GROUPE';if(document.documentElement.dataset.page==='news')document.title=({th:'ข่าวสาร',lo:'ຂ່າວສານ',en:'News'})[lang]+' — LOVE STK GROUPE';if(document.documentElement.dataset.page==='about')document.title=({th:'เกี่ยวกับเรา',lo:'ກ່ຽວກັບພວກເຮົາ',en:'About us'})[lang]+' — LOVE STK GROUPE';if(document.documentElement.dataset.page==='businesses')document.title=({th:'ธุรกิจของเรา',lo:'ທຸລະກິດຂອງເຮົາ',en:'Our businesses'})[lang]+' — LOVE STK GROUPE';if(['products','product-detail'].includes(document.documentElement.dataset.page))document.title=translations[lang].productsTitle+' — LOVE STK GROUPE';menu.setAttribute('aria-label',({th:'เปิดเมนู',lo:'ເປີດເມນູ',en:'Open navigation'})[lang]);try{localStorage.setItem('stk-language',lang)}catch(e){}document.querySelectorAll('[data-executive-role]').forEach(img=>img.alt=({th:'ภาพบุคคลสมมติสำหรับตำแหน่ง ',lo:'ຮູບບຸກຄົນສົມມຸດສຳລັບຕຳແໜ່ງ ',en:'Fictional portrait for the role of '})[lang]+img.dataset.executiveRole);document.dispatchEvent(new Event('stk-language-change'));}
